  [286153] = { "Plated Armorfishの調理法を習得します。", 0xc3253d40, "u" },
  [286176] = { "Deathguardの一員を鼓舞します。", 0x664cd0c8, "u" },
  [286263] = { "凍てつく北への遠征で、聖なる光が私たちを守ってくださいますように。", 0xeee6c8a9, "u" },
  [286264] = { "メイジの皆さんには、自分の……本の中から頭を出してほしいものです。", 0x2fdc6df9, "u" },
  [286265] = { "妹たちがその力を存分に発揮し、その功績によってWindrunnerの名が知られますように。", 0x5658f716, "u" },
  [286266] = { "変えられないものを受け入れる強さと、変えられるものを変える勇気と、その違いを見分ける知恵を私にお与えください。", 0xa430a556, "u" },
  [286267] = { "ああ、どうして私に気づいてくれないの？ Abbendis、あなたのためならどこへでもついていくのに。私に気づいてくれたらいいのに……", 0x54ac42ab, "u" },
  [286268] = { "その時が来たとき、門の向こうの軍勢を阻む強さが私にありますように。", 0x06550e08, "u" },
  [286270] = { "この泉、いったいどういう仕組みなんだろう？ 自分でも作れるかな。", 0x9e07f333, "u" },
  [286271] = { "TuralyonとAlleria、どこにいようとも、どうか元気でいますように。", 0xc8d073fa, "u" },
  [286272] = { "息子Arthasが、常に民のために最善を尽くしますように。", 0xdd75c0be, "u" },
  [286273] = { "Illidanはどこ？", 0xf4f231cf, "u" },
  [286274] = { "<頭の中で三つの音が鳴り響くのを感じます。三つ目の音は、ほかの音の喧騒にかき消されてほとんど聞こえません。>", 0x9917df10, "u" },
  [286275] = { "父上と兄上たちが私より長生きしますように。私はたいした王にはなれないでしょう。", 0x4da49bfd, "u" },
  [286279] = { "早く大人になりたい。もう何年も$N1歳のままのような気がする。", 0xb991d825, "u" },
  [286280] = { "若きArthasは、その力を和らげるために忍耐を学ばねばなりません。いつの日か、彼が力ではなく思いやりをもって導くことを学べるよう祈ります。", 0xbb389a87, "u" },
  [286281] = { "すでに私には王国という将来の見込みがあり、治めるべき土地がある。何を願おうか？ 凍ったスコーンでも……", 0xd1122935, "u" },
  [286283] = { "いつか、自分だけのこぢんまりとした屋敷に隠居して、たくさんの犬たちに囲まれて暮らしたい。", 0xd20396c6, "u" },
  [286284] = { "Brann Bronzebeard参上。", 0x851089b6, "u" },
  [286287] = { "ときどき……誰かがやって来て、ただぎゅっと長く抱きしめてくれたらと思う。", 0xc021960f, "u" },
  [286288] = { "Arthas、愛しい人、どうか私のもとへ戻ってきて。", 0x75d29e0f, "u" },
  [286290] = { "いいか、小さな願いの泉よ。身のためを思うなら、お前の力をすべて私によこすのだ。", 0xdae8a1fb, "u" },
  [286291] = { "妹たちと一緒に大人になって、一緒に結婚できますように。この硬貨はとても古いもののようです。", 0x11a6603a, "u" },
  [286292] = { "愛しいTaelanが、大切に思う人々を守れるほど強く育ちますように。", 0x5c5303f2, "u" },
  [286293] = { "小さな泉よ、お前がどうやって我が怒りを生き延びたのか知りたいものだ。", 0x3846ac8d, "u" },
  [286294] = { "私の夢を解き明かしておくれ、小さな泉よ。なぜ私はいつも同胞を上から見下ろし、駒のように動かしていなければならないのだろう？", 0x275f4627, "u" },
  [286298] = { "郵便配達員としての副業の日々も、そろそろ終わりのようです。", 0x7cf94019, "u" },
  [286299] = { "Grom、安らかに眠れ、古き友よ。", 0xb8d72ae3, "u" },
  [286300] = { "わけがわからない。どうして私は泉に硬貨を入れているんだろう？", 0xa022f596, "u" },
  [286302] = { "池の中でこんなにたくさんの硬貨が光っている……一枚くらい取っても誰も気づかないかも。", 0x5b57d231, "u" },
  [286304] = { "いとこみたいに、ただ木材をのんきに運び回るだけの仕事だったらよかったのに……", 0xf77f1f2f, "u" },
  [286306] = { "Captain Sandersがワインの積み荷を早く届けてくれますように。", 0x38184765, "u" },
  [286307] = { "娘の幸せと、娘が受け入れられることを願います。あの子はここでひどく居心地が悪そうで……", 0x2dd81161, "u" },
  [286308] = { "もっと座り心地のいい鞍をもらえませんか？ お尻が痛くて。", 0xc0d11bc5, "u" },
  [286309] = { "トロールが死にますように、今……すぐに。", 0x5c88ac6d, "u" },
  [286310] = { "ローグでいるのは大変な仕事だ。いつか、人生でただひとつの本当の情熱を追いかけたい……", 0xb0b1aeae, "u" },
  [286311] = { "いつかまた別の本に登場できますように。", 0x1e072bac, "u" },
  [286312] = { "父を返してほしい……", 0xb0bf1a4d, "u" },
  [286313] = { "あの硬貨を取っておけばよかった……", 0xfbe57df5, "u" },
