  [286315] = { "この銅貨は、何か役に立つことに使えたかもしれない。たとえば、糸と機械を使う何かとか。", 0x73a4a2cf, "u" },
  [286316] = { "ここは魔法の気配すらありません。", 0x106f5f9e, "u" },
